WITH web_events_by_session AS (SELECT session_id, MAX(duration_sec) - MIN(duration_sec) AS duration_sec_range, ROUND((100 * SUM(CASE WHEN page = '/cart' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_cart FROM web_events WHERE event_type = 'page_view' GROUP BY session_id) SELECT s.id, s.started_at, s.device, webs.duration_sec_range, webs.pct_cart FROM sessions s INNER JOIN web_events_by_session webs ON s.id = webs.session_id WHERE webs.duration_sec_range >= 77 ORDER BY duration_sec_range;
